CREATE TABLE IF NOT EXISTS resources(id TEXT PRIMARY KEY, project TEXT NOT NULL, kind TEXT NOT NULL, name TEXT NOT NULL, body TEXT NOT NULL, created REAL NOT NULL);
CREATE TABLE IF NOT EXISTS runs(id TEXT PRIMARY KEY, project TEXT NOT NULL, name TEXT NOT NULL, spec TEXT NOT NULL, status TEXT NOT NULL, created REAL NOT NULL, updated REAL NOT NULL, idem TEXT NOT NULL, digest TEXT NOT NULL, error TEXT, UNIQUE(project,idem));
CREATE TABLE IF NOT EXISTS results(id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES runs(id), case_id TEXT NOT NULL, repetition INTEGER NOT NULL, body TEXT NOT NULL, UNIQUE(run_id,case_id,repetition));
CREATE TABLE IF NOT EXISTS reviews(id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES runs(id), case_id TEXT NOT NULL, repetition INTEGER NOT NULL, decision TEXT NOT NULL, reason TEXT NOT NULL, created REAL NOT NULL);
